// Canonicalize inputs from either (a) Form Trigger v2.2 which emits values keyed
// by fieldLabel, or (b) Webhook Trigger which wraps the POST body under .body.
const input = $input.first().json;
const form = (input && typeof input.body === 'object' && input.body !== null && Object.keys(input.body).length > 0)
  ? input.body
  : input;

const norm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
const pick = (...keys) => {
  for (const k of keys) {
    if (form[k] !== undefined && form[k] !== null && form[k] !== '') return form[k];
  }
  const targets = keys.map(norm);
  for (const k of Object.keys(form)) {
    const n = norm(k);
    if (targets.some(t => n === t || n.startsWith(t))) return form[k];
  }
  return '';
};

// Parse competitors: array from webhook body, or JSON string from Form Trigger field.
let competitorsRaw = pick('competitors', 'competitors_json', 'Named Competitors');
let competitors = [];
if (Array.isArray(competitorsRaw)) {
  competitors = competitorsRaw;
} else if (typeof competitorsRaw === 'string' && competitorsRaw.trim()) {
  try { competitors = JSON.parse(competitorsRaw); }
  catch { competitors = []; }
}
competitors = (Array.isArray(competitors) ? competitors : [])
  .map(c => ({ name: String(c.name || '').trim(), url: String(c.url || '').trim() }))
  .filter(c => c.name || c.url)
  .slice(0, 5);

return [{
  json: {
    search_term: pick('search_term', 'Search Term', 'searchTerm'),
    location: pick('location', 'Location'),
    target_business_name: pick('target_business_name', 'Target Business Name', 'targetBusinessName'),
    target_website: pick('target_website', 'Target Website', 'targetWebsite') || '',
    competitors,
    neuronwriter_api_key: pick('neuronwriter_api_key', 'NeuronWriter API Key', 'neuronwriterApiKey') || '',
    neuronwriter_project_id: pick('neuronwriter_project_id', 'NeuronWriter Project ID', 'neuronwriterProjectId') || '',
    _raw_form: form
  }
}];

// Competitor Enrichment
// Builds a unified competitor set from (a) user-supplied named competitors
// and (b) SERP top organic + local pack winners, then enriches each with:
//   - DataForSEO domain rank + referring domains (one bulk call per metric)
//   - Knowledge Graph entity (per competitor)
//   - Google Business Profile with full attribute fieldMask (per competitor)
//   - DataForSEO on_page/content_parsing (user-supplied competitors only -- cost control)
// Also geocodes the search-center location and computes Haversine distance
// from search center for the target + every competitor.

const form = $('Normalize Form').first().json;
const serpRaw = $('DataForSEO SERP').first().json;
const placesRaw = $('Places Text Search').first().json;

const GOOGLE_KEY = 'AIzaSyCtMJUgY5Wqp1mIssepbVCpRorXqkxr2B8';
const PLACES_KEY = 'AIzaSyBT6gGScuYDlhyvRNZ58zSQiK-iS3rOukM';
const DFS_AUTH = 'Basic ' + Buffer.from('abhishekbolarshetty@gmail.com:6aa69ca0a4bf8188').toString('base64');
const PLACES_FIELD_MASK = 'places.displayName,places.formattedAddress,places.rating,places.userRatingCount,places.types,places.primaryType,places.websiteUri,places.regularOpeningHours,places.editorialSummary,places.photos,places.location,places.priceLevel,places.paymentOptions,places.parkingOptions,places.accessibilityOptions,places.goodForChildren,places.goodForGroups,places.reservable,places.businessStatus,places.shortFormattedAddress';

const tryHost = (url) => {
  if (!url) return '';
  try { return new URL(url).hostname.replace(/^www\./, '').toLowerCase(); }
  catch { return String(url).replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].toLowerCase(); }
};

const haversine = (a, b) => {
  if (!a || !b || a.lat == null || b.lat == null) return null;
  const toRad = d => d * Math.PI / 180;
  const R = 6371;
  const dLat = toRad(b.lat - a.lat);
  const dLon = toRad(b.lng - a.lng);
  const lat1 = toRad(a.lat);
  const lat2 = toRad(b.lat);
  const h = Math.sin(dLat/2) ** 2 + Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLon/2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(h), Math.sqrt(1 - h));
};

// 1) Assemble competitor list -- user first, then SERP organic top 3, then local pack top 3.
const userList = (form.competitors || [])
  .map(c => ({
    source: 'user',
    name: (c.name || '').trim(),
    url: (c.url || '').trim(),
    domain: tryHost(c.url)
  }))
  .filter(c => c.name || c.url)
  .slice(0, 5);

const dfsItems = serpRaw.tasks?.[0]?.result?.[0]?.items || [];
const topOrganic = dfsItems
  .filter(i => i.type === 'organic')
  .slice(0, 3)
  .map(i => ({
    source: 'serp',
    name: i.title,
    url: i.url,
    domain: (i.domain || tryHost(i.url) || '').replace(/^www\./, '').toLowerCase(),
    serp_position: i.rank_absolute,
    serp_snippet: i.description
  }));
const localPack = dfsItems
  .filter(i => i.type === 'local_pack')
  .slice(0, 3)
  .map(p => ({
    source: 'serp_local_pack',
    name: p.title,
    url: p.url,
    domain: tryHost(p.url),
    serp_position: p.rank_absolute,
    local_pack_rating: p.rating?.value,
    local_pack_rating_count: p.rating?.votes_count,
    cid: p.cid
  }));

const seen = new Set();
const competitors = [];
const pushIfNew = (c) => {
  const key = (c.domain || c.name || '').toLowerCase();
  if (!key || seen.has(key)) return;
  seen.add(key);
  competitors.push(c);
};
userList.forEach(pushIfNew);
topOrganic.forEach(pushIfNew);
localPack.forEach(pushIfNew);

// 2) Target info
const targetDomain = tryHost(form.target_website);
const targetPlace = placesRaw.places?.[0] || null;
const targetLatLng = targetPlace?.location
  ? { lat: targetPlace.location.latitude, lng: targetPlace.location.longitude }
  : null;

// 3) Geocode search center
let searchCenter = null;
try {
  const geoRes = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://maps.googleapis.com/maps/api/geocode/json',
    qs: { address: form.location, key: GOOGLE_KEY },
    json: true
  });
  const loc = geoRes.results?.[0]?.geometry?.location;
  if (loc) searchCenter = { lat: loc.lat, lng: loc.lng, formatted: geoRes.results[0].formatted_address };
} catch (e) { /* non-fatal */ }

// 4) Bulk DataForSEO calls for all domains (target + competitors)
const allDomains = [...new Set([targetDomain, ...competitors.map(c => c.domain)].filter(Boolean))];

const bulkRanksReq = allDomains.length
  ? this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.dataforseo.com/v3/backlinks/bulk_ranks/live',
      headers: { 'Authorization': DFS_AUTH, 'Content-Type': 'application/json' },
      body: [{ targets: allDomains }],
      json: true
    }).catch(() => null)
  : Promise.resolve(null);

const bulkRefReq = allDomains.length
  ? this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.dataforseo.com/v3/backlinks/bulk_referring_domains/live',
      headers: { 'Authorization': DFS_AUTH, 'Content-Type': 'application/json' },
      body: [{ targets: allDomains }],
      json: true
    }).catch(() => null)
  : Promise.resolve(null);

const [bulkRanksRes, bulkRefRes] = await Promise.all([bulkRanksReq, bulkRefReq]);

const rankMap = {};
(bulkRanksRes?.tasks?.[0]?.result?.[0]?.items || []).forEach(i => { rankMap[i.target] = i.rank; });
const refMap = {};
(bulkRefRes?.tasks?.[0]?.result?.[0]?.items || []).forEach(i => { refMap[i.target] = i.referring_domains; });

// 5) Per-competitor: KG + Places + (user only) on-page parsing -- all in parallel
const enrichOne = async (c) => {
  const enriched = { ...c };
  enriched.dataforseo_rank = c.domain ? (rankMap[c.domain] ?? null) : null;
  enriched.referring_domains = c.domain ? (refMap[c.domain] ?? null) : null;

  const kgPromise = c.name
    ? this.helpers.httpRequest({
        method: 'GET',
        url: 'https://kgsearch.googleapis.com/v1/entities:search',
        qs: { query: `${c.name} ${form.location}`, limit: 1, key: GOOGLE_KEY },
        json: true
      }).catch(() => null)
    : Promise.resolve(null);

  const placesPromise = c.name
    ? this.helpers.httpRequest({
        method: 'POST',
        url: 'https://places.googleapis.com/v1/places:searchText',
        headers: {
          'Content-Type': 'application/json',
          'X-Goog-Api-Key': PLACES_KEY,
          'X-Goog-FieldMask': PLACES_FIELD_MASK
        },
        body: { textQuery: `${c.name} ${form.location}` },
        json: true
      }).catch(() => null)
    : Promise.resolve(null);

  const onPagePromise = (c.source === 'user' && c.url)
    ? this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.dataforseo.com/v3/on_page/content_parsing/live',
        headers: { 'Authorization': DFS_AUTH, 'Content-Type': 'application/json' },
        body: [{ url: c.url }],
        json: true
      }).catch(() => null)
    : Promise.resolve(null);

  const [kgRes, placesRes, opRes] = await Promise.all([kgPromise, placesPromise, onPagePromise]);

  const kgItem = kgRes?.itemListElement?.[0]?.result || null;
  enriched.kg = kgItem ? {
    name: kgItem.name,
    type: kgItem['@type'],
    description: kgItem.description,
    detailedDescription: kgItem.detailedDescription?.articleBody
  } : null;

  const place = placesRes?.places?.[0] || null;
  if (place) {
    enriched.gbp = {
      displayName: place.displayName?.text,
      formattedAddress: place.formattedAddress,
      shortFormattedAddress: place.shortFormattedAddress,
      rating: place.rating,
      userRatingCount: place.userRatingCount,
      primaryType: place.primaryType,
      types: place.types,
      websiteUri: place.websiteUri,
      hours: place.regularOpeningHours?.weekdayDescriptions,
      photoCount: (place.photos || []).length,
      priceLevel: place.priceLevel,
      attributes: {
        paymentOptions: place.paymentOptions,
        parkingOptions: place.parkingOptions,
        accessibilityOptions: place.accessibilityOptions,
        goodForChildren: place.goodForChildren,
        goodForGroups: place.goodForGroups,
        reservable: place.reservable
      },
      businessStatus: place.businessStatus,
      location: place.location ? { lat: place.location.latitude, lng: place.location.longitude } : null
    };
  } else {
    enriched.gbp = null;
  }

  enriched.distance_from_search_center_km = (searchCenter && enriched.gbp?.location)
    ? Math.round(haversine(searchCenter, enriched.gbp.location) * 10) / 10
    : null;

  if (opRes) {
    const page = opRes.tasks?.[0]?.result?.[0]?.items?.[0]?.page_content || {};
    const meta = opRes.tasks?.[0]?.result?.[0]?.items?.[0]?.meta || {};
    enriched.on_page = {
      title: meta.title || page.title,
      meta_description: meta.description || page.meta?.description,
      h1: (page.header?.h1 && page.header.h1[0]) || meta.htags?.h1?.[0] || null,
      h2: (page.header?.h2 || meta.htags?.h2 || []).slice(0, 15),
      h3_count: (page.header?.h3 || meta.htags?.h3 || []).length,
      word_count: meta.content?.plain_text_word_count || page.word_count || null
    };
  } else {
    enriched.on_page = null;
  }

  return enriched;
};

const enrichedCompetitors = await Promise.all(competitors.map(enrichOne));

const targetDistance = (searchCenter && targetLatLng)
  ? Math.round(haversine(searchCenter, targetLatLng) * 10) / 10
  : null;

return [{
  json: {
    competitor_enrichment: {
      competitors: enrichedCompetitors,
      target: {
        domain: targetDomain,
        dataforseo_rank: targetDomain ? (rankMap[targetDomain] ?? null) : null,
        referring_domains: targetDomain ? (refMap[targetDomain] ?? null) : null,
        location: targetLatLng,
        distance_from_search_center_km: targetDistance
      },
      search_center: searchCenter,
      count: { user: userList.length, serp: enrichedCompetitors.length - userList.filter(u => seen.has((u.domain || u.name).toLowerCase())).length, total: enrichedCompetitors.length }
    }
  }
}];

// NeuronWriter add-on enrichment. Skips cleanly when no credentials provided.
const form = $('Normalize Form').first().json;
const apiKey = (form.neuronwriter_api_key || '').trim();
const projectId = (form.neuronwriter_project_id || '').trim();

if (!apiKey || !projectId) {
  return [{ json: { neuronwriter: null, neuronwriter_status: 'disabled' } }];
}

const BASE = 'https://app.neuronwriter.com/neuron-api/0.5/writer';
const headers = {
  'X-API-KEY': apiKey,
  'Content-Type': 'application/json',
  'Accept': 'application/json'
};
const sleep = ms => new Promise(r => setTimeout(r, ms));

try {
  const newQueryRes = await this.helpers.httpRequest({
    method: 'POST',
    url: BASE + '/new-query',
    headers,
    body: { project: projectId, keyword: form.search_term, engine: 'google.com', language: 'English' },
    json: true
  });

  const queryId = newQueryRes.query || newQueryRes.id || newQueryRes.query_id;
  if (!queryId) {
    return [{ json: { neuronwriter: null, neuronwriter_status: 'error', neuronwriter_error: 'new-query did not return a query id', neuronwriter_raw: newQueryRes } }];
  }

  // Poll get-query -- budget ~3 min: 45s initial wait, then up to 9 polls at 15s each
  await sleep(45000);

  let data = null;
  let lastStatus = null;
  for (let i = 0; i < 10; i++) {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: BASE + '/get-query',
      headers,
      body: { query: queryId },
      json: true
    });
    lastStatus = resp.status;
    if (resp.status === 'ready') { data = resp; break; }
    if (resp.status === 'failed' || resp.status === 'error') {
      return [{ json: { neuronwriter: null, neuronwriter_status: 'error', neuronwriter_error: resp.status, neuronwriter_raw: resp } }];
    }
    await sleep(15000);
  }

  if (!data) {
    return [{ json: { neuronwriter: null, neuronwriter_status: 'timeout', neuronwriter_query_id: queryId, neuronwriter_last_status: lastStatus } }];
  }

  // Defensive extraction -- NeuronWriter's response schema varies
  const terms = data.terms || {};
  const competitors = data.competitors || [];
  const termToStr = t => typeof t === 'string' ? t : (t && (t.t || t.term || t.text) || '');
  const getArr = (obj, ...keys) => {
    for (const k of keys) {
      if (obj && Array.isArray(obj[k])) return obj[k];
    }
    return [];
  };
  const clean = arr => arr.map(termToStr).filter(Boolean);
  const uniq = arr => [...new Set(arr)];

  const h1FromTerms = clean(getArr(terms, 'h1'));
  const h2FromTerms = clean(getArr(terms, 'h2'));
  const competitorHeadings = [];
  for (const c of competitors.slice(0, 10)) {
    const hs = c.headings || c.h || [];
    for (const h of hs) {
      const text = typeof h === 'string' ? h : (h && (h.text || h.t) || '');
      if (text) competitorHeadings.push(text);
    }
  }

  const basicTerms = clean(getArr(terms, 'content_basic', 'basic', 'b')).slice(0, 40);
  const extendedTerms = clean(getArr(terms, 'content_extended', 'extended', 'e')).slice(0, 30);
  const titleTerms = clean(getArr(terms, 'title', 't')).slice(0, 20);

  const entitiesRaw = data.entities || terms.entities || [];
  const entities = clean(Array.isArray(entitiesRaw) ? entitiesRaw : []).slice(0, 30);

  const questionsRaw = data.questions || terms.questions || data.suggested_queries || [];
  const articleQueries = clean(Array.isArray(questionsRaw) ? questionsRaw : []).slice(0, 20);

  return [{
    json: {
      neuronwriter: {
        query_id: queryId,
        headings: uniq([...h1FromTerms, ...h2FromTerms, ...competitorHeadings]).slice(0, 40),
        terms: { basic: basicTerms, extended: extendedTerms, title: titleTerms, h1: h1FromTerms },
        entities,
        article_queries: articleQueries,
        content_score_target: data.content_score_target || data.target_score || null
      },
      neuronwriter_status: 'ready'
    }
  }];
} catch (err) {
  return [{ json: { neuronwriter: null, neuronwriter_status: 'error', neuronwriter_error: String(err && err.message ? err.message : err) } }];
}

// Pull canonical inputs from Normalize Form
const form = $('Normalize Form').first().json;
const search_term = form.search_term || '';
const location = form.location || '';
const target_business_name = form.target_business_name || '';
const target_website = form.target_website || '';

// Pull API responses
const kgRaw = $('KG Search').first().json;
const placesRaw = $('Places Text Search').first().json;
const serpRaw = $('DataForSEO SERP').first().json;

// Pull Competitor Enrichment output
const enrichmentOut = $('Competitor Enrichment').first().json;
const enrichment = enrichmentOut.competitor_enrichment || { competitors: [], target: {}, search_center: null };

// Pull NeuronWriter add-on output (null when disabled/failed)
const nwOutput = $('NeuronWriter Enrichment').first().json;
const neuron = nwOutput.neuronwriter || null;
const neuronStatus = nwOutput.neuronwriter_status || 'disabled';

// ---------- Prune KG ----------
const kgItem = (kgRaw.itemListElement && kgRaw.itemListElement[0]) || null;
const kg = kgItem ? {
  name: kgItem.result?.name,
  type: kgItem.result?.['@type'],
  description: kgItem.result?.description,
  detailedDescription: kgItem.result?.detailedDescription?.articleBody,
  url: kgItem.result?.url,
  resultScore: kgItem.resultScore
} : { note: 'No KG entity found' };

// ---------- Prune Places (target) ----------
const place = (placesRaw.places && placesRaw.places[0]) || {};
const gbp = {
  displayName: place.displayName?.text,
  formattedAddress: place.formattedAddress,
  shortFormattedAddress: place.shortFormattedAddress,
  rating: place.rating,
  userRatingCount: place.userRatingCount,
  types: place.types,
  primaryType: place.primaryType,
  websiteUri: place.websiteUri,
  hours: place.regularOpeningHours?.weekdayDescriptions,
  editorialSummary: place.editorialSummary?.text,
  photoCount: (place.photos || []).length,
  priceLevel: place.priceLevel,
  businessStatus: place.businessStatus,
  attributes: {
    paymentOptions: place.paymentOptions,
    parkingOptions: place.parkingOptions,
    accessibilityOptions: place.accessibilityOptions,
    goodForChildren: place.goodForChildren,
    goodForGroups: place.goodForGroups,
    reservable: place.reservable
  },
  dataforseo_domain_rank: enrichment.target?.dataforseo_rank ?? null,
  referring_domains: enrichment.target?.referring_domains ?? null,
  distance_from_search_center_km: enrichment.target?.distance_from_search_center_km ?? null,
  search_center_address: enrichment.search_center?.formatted ?? null
};

// ---------- Prune DataForSEO SERP ----------
const dfsResult = serpRaw.tasks?.[0]?.result?.[0];
const items = dfsResult?.items || [];

const organic = items
  .filter(i => i.type === 'organic')
  .slice(0, 10)
  .map(r => ({
    position: r.rank_absolute,
    title: r.title,
    link: r.url,
    snippet: r.description,
    domain: r.domain
  }));

const localPack = items
  .filter(i => i.type === 'local_pack')
  .slice(0, 3)
  .map(p => ({
    title: p.title,
    description: p.description,
    rating: p.rating?.value,
    ratingCount: p.rating?.votes_count,
    url: p.url,
    cid: p.cid
  }));

const knowledgeGraph = items.find(i => i.type === 'knowledge_graph') || null;
const answerBox = items.find(i => i.type === 'answer_box') || items.find(i => i.type === 'featured_snippet') || null;
const aiOverviewItem = items.find(i => i.type === 'ai_overview');
const aiOverview = aiOverviewItem ? { text: aiOverviewItem.text, references: aiOverviewItem.references } : null;
const paaItem = items.find(i => i.type === 'people_also_ask');
const peopleAlsoAsk = paaItem ? (paaItem.items || []).slice(0, 5).map(q => q.title) : [];
const relatedItem = items.find(i => i.type === 'related_searches');
const relatedSearches = relatedItem ? (relatedItem.items || []).slice(0, 5) : [];

const serpFeaturesPresent = [...new Set(items.map(i => i.type))];

const serp = {
  organic,
  localPack,
  knowledgeGraph,
  answerBox,
  aiOverview,
  peopleAlsoAsk,
  relatedSearches,
  serpFeaturesPresent
};

// ---------- Build Gemini prompts ----------
const systemPrompt = `You are a senior local search analyst. Your job is to produce an actionable ranking plan -- not a description, not a summary -- for a specific business trying to rank for a specific search term in a specific location.

GROUNDING RULES (non-negotiable):
1. Only use facts present in the <data> blocks. If a fact is not in the data, write "not available in provided data" -- do not infer or estimate.
2. Every claim must cite a source: [KG], [GBP], [SERP], [COMPETITOR:N] (N is the 1-based index in the COMPETITORS array), or [NEURON].
3. If data sources contradict, treat live sources (GBP, SERP, COMPETITORS) as truth and flag the discrepancy.
4. Do not recommend any action that cannot be justified by a specific gap in the data. If you cannot justify an action, do not include it.
5. The COMPETITORS array includes both user-supplied rivals (source='user') and SERP-discovered winners (source='serp' or 'serp_local_pack'). User-supplied competitors are strategically important even if they don't currently rank; SERP competitors prove what Google rewards. Use BOTH lenses.

ANALYSIS FRAMEWORK:
- Infer search intent from SERP features.
- Identify SERP features present and which ones the target does not appear in.
- For competitive_gaps, compare target's GBP/website signals against the COMPETITORS array. Use concrete numbers: domain rank (dataforseo_rank, scale 0-1000), referring_domains, userRatingCount, photoCount, distance_from_search_center_km, attribute presence (paymentOptions/parkingOptions/etc), on_page headings + word_count where available.
- Distance: if target's distance_from_search_center_km is materially higher than competitors', call this out as a structural geographic gap.
- Classify gaps: 30 days (reviews, photos, posts, GBP attributes), 90 days (content, citations, on-page schema, headings), structural (domain rank/referring domains gap, category change, location).

NEURON ADD-ON: If NEURON data is present (non-empty object), populate content_suggestions with up to 10 items drawn from NEURON headings, terms, entities, and article_queries. Pick items that address visible gaps in SERP features, competitor coverage, or intent coverage. Cite [NEURON]. If NEURON data reads 'not enabled', return content_suggestions as an empty array and do not reference NEURON anywhere.

TONE: Direct, prescriptive, no hedging. Avoid "consider", "might", "could". Use "do X because Y shows Z".

OUTPUT: Valid JSON only. No prose outside the JSON. No markdown code fences.`;

const userPrompt = `SEARCH TERM: ${search_term}
LOCATION: ${location}
TARGET BUSINESS: ${target_business_name}
TARGET WEBSITE: ${target_website}

<data source="KG">
${JSON.stringify(kg, null, 2)}
</data>

<data source="GBP">
${JSON.stringify(gbp, null, 2)}
</data>

<data source="SERP">
${JSON.stringify(serp, null, 2)}
</data>

<data source="COMPETITORS" note="Indexed array; cite specific competitors with [COMPETITOR:N] using the 1-based index.">
${JSON.stringify(enrichment.competitors || [], null, 2)}
</data>

<data source="NEURON" note="Optional add-on. If body reads 'not enabled', do not cite NEURON and leave content_suggestions empty.">
${neuron ? JSON.stringify(neuron, null, 2) : 'not enabled'}
</data>

Produce a ranking plan as valid JSON matching this exact schema:
{
  "search_term": "string",
  "search_intent": "informational | transactional | local | commercial",
  "serp_features_present": ["array of strings"],
  "target_current_visibility": {
    "ranks_in_local_pack": "boolean or rank position",
    "ranks_in_organic_top_10": "boolean or rank position",
    "appears_in_knowledge_panel": "boolean",
    "visibility_summary": "one sentence with citations"
  },
  "competitive_gaps": [
    { "gap": "string", "evidence": "string with concrete numbers from COMPETITORS / GBP / SERP", "citation": "[COMPETITOR:N] or [SERP] or [GBP]" }
  ],
  "data_discrepancies": [
    { "field": "string", "kg_value": "string", "live_value": "string", "action": "string" }
  ],
  "prioritized_actions": [
    { "action": "string", "priority": "P0|P1|P2", "effort": "low|medium|high", "expected_impact": "string", "evidence_basis": "string", "timeframe": "this week|30 days|90 days|structural" }
  ],
  "quick_wins": ["top 3 P0 low-effort actions verbatim"],
  "content_suggestions": [
    { "suggestion": "string", "type": "heading|term|entity|query", "citation": "[NEURON]", "rationale": "one sentence tying to a specific gap in target coverage" }
  ],
  "cannot_assess": ["questions needing more data -- do NOT list items already covered by COMPETITORS (domain rank, referring domains, GBP attributes, distance) or by NEURON"]
}

Return only JSON.`;

return [{
  json: {
    search_term,
    location,
    target_business_name,
    target_website,
    pruned: { kg, gbp, serp, neuron, neuron_status: neuronStatus, competitor_enrichment: enrichment },
    gemini_request: {
      systemInstruction: { parts: [{ text: systemPrompt }] },
      contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
      generationConfig: {
        temperature: 0.2,
        responseMimeType: 'application/json'
      }
    }
  }
}];

// Extract the JSON plan from Gemini's response
const response = $input.first().json;
const text = response.candidates?.[0]?.content?.parts?.[0]?.text;

if (!text) {
  return [{ json: { error: 'No text in Gemini response', raw: response } }];
}

let plan;
try {
  plan = JSON.parse(text);
} catch (e) {
  const cleaned = text.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
  try {
    plan = JSON.parse(cleaned);
  } catch (e2) {
    return [{ json: { error: 'Failed to parse JSON from Gemini', raw_text: text } }];
  }
}

const inputs = $('Build Gemini Payload').first().json;
const neuron = inputs.pruned && inputs.pruned.neuron ? inputs.pruned.neuron : null;
const neuronStatus = inputs.pruned && inputs.pruned.neuron_status ? inputs.pruned.neuron_status : 'disabled';
const competitorEnrichment = inputs.pruned && inputs.pruned.competitor_enrichment ? inputs.pruned.competitor_enrichment : null;
const targetEnrichment = competitorEnrichment ? competitorEnrichment.target : null;
const targetGbp = inputs.pruned && inputs.pruned.gbp ? inputs.pruned.gbp : null;

return [{
  json: {
    request: {
      search_term: inputs.search_term,
      location: inputs.location,
      target_business_name: inputs.target_business_name,
      target_website: inputs.target_website
    },
    plan,
    neuronwriter: neuron,
    neuronwriter_status: neuronStatus,
    competitor_enrichment: competitorEnrichment,
    target_enrichment: targetEnrichment,
    target_gbp: targetGbp,
    generated_at: new Date().toISOString()
  }
}];
